IsDecorationIndexInSecretBase.body:
u8 i;
    for (i = 0; i < ARRAY_COUNT(sSecretBaseItemsIndicesBuffer); i++)
    {
        if (sSecretBaseItemsIndicesBuffer[i] == idx)
            return TRUE;
    }

    return FALSE;

IsDecorationIndexInPlayersRoom.body:
u8 i;
